def check(world, calls):
    valid = [c for c in calls if c.name == "verify_policyholder" and c.ok and c.arguments.get("factor") in ("dob", "zip", "last4_ssn") and c.arguments.get("answer")]
    if not valid:
        return "Caller identity was not successfully verified with a valid factor"
    return None

